    1  // dedupe.js — collapse items that appear in more than one feed.
    2  // Strategy: a stable GUID wins; otherwise fall back to a normalized
    3  // title+link fingerprint so cross-posted stories still merge.
    4  
    5  export function dedupe(items) {
    6    const seen = new Map();
    7    for (const item of items) {
    8      const key = fingerprint(item);
    9      const prev = seen.get(key);
   10      // Keep the earliest-published copy; record every source it came from.
   11      if (!prev) {
   12        seen.set(key, { ...item, sources: [item.source] });
