Realized P&L needs lot matching, so I'll write a FIFO calculator instead of guessing.
{"name":"write_file","arguments":{"path":"pnl.mjs","content":"// Realized P&L per ticker using FIFO lot matching.
// Usage: node pnl.mjs [trades.csv]  -> prints per-ticker + overall realized P&L.
import { readFileSync } from "node:fs";

const path = process.argv[2] ?? "trades.csv";
const rows = readFileSync(path, "utf8").trim().split("\n").slice(1);

const trades = rows.map((line) => {
  const [ticker, side, qty, price, date] = line.split(",");
  return { ticker, side, qty: Number(qty), price: Number(price), date };
});
trades.sort((a, b) => a.date.localeCompare(b.date));

const lots = {};       // ticker -> FIFO queue of open buy lots
const realized = {};   // ticker -> realized P&L

for (const t of trades) {
  lots[t.ticker] ??= [];
  realized[t.ticker] ??= 0;
  if (t.side === "buy") {
    lots[t.ticker].push({ qty: t.qty, price: t.price });
  } else {
    let remaining = t.qty;
    while (remaining > 0) {
      const lot = lots[t.ticker][0];
      if (!lot) throw new Error(`Oversell on ${t.ticker} (${t.date})`);
      const matched = Math.min(lot.qty, remaining);
      realized[t.ticker] += matched * (t.price - lot.price);
      lot.qty -= matched;
      remaining -= matched;
      if (lot.qty === 0) lots[t.ticker].shift();
    }
  }
}

let overall = 0;
const perTicker = Object.keys(realized)
  .sort()
  .map((tk) => {
    overall += realized[tk];
    const open = (lots[tk] ?? []).reduce((s, l) => s + l.qty, 0);
    return { ticker: tk, realized: realized[tk], openQty: open };
  });

const fmt = (n) => (n < 0 ? "-$" : "$") + Math.abs(n).toFixed(2);
export { perTicker, overall, fmt };

if (import.meta.url === `file://${process.argv[1]}`) {
  for (const r of perTicker) {
    console.log(`${r.ticker.padEnd(6)} realized=${fmt(r.realized).padStart(12)}  open=${r.openQty}`);
  }
  console.log(`OVERALL realized P&L = ${fmt(overall)}`);
}
"}}

