const joists = Math.floor(W / joistSpacing) + 1;   // +1 for the closing joist
const joistBoards = joists;                   // one 2x8x12 each
const ledger = 1;                             // 2x8x16
const rim = 3;                                // outer band: 1x16ft + 2x12ft -> 3 boards
const beamBoards = 2;                         // doubled 2x8x16

// --- Foundation (beam posts at 0/8/16 ft -> 3 footings) ---
const posts = Math.ceil(W / 8) + 1;           // 3
const footings = posts;
const r = 0.5, h = 42 / 12;                    // 12" dia x 42" deep pier
const pierCf = Math.PI * r * r * h;           // cu ft each
const concreteCf = pierCf * footings;
const bag60Yield = 0.45;                       // cu ft per 60 lb bag
const concreteBags = Math.ceil(concreteCf / bag60Yield);

// --- Decking (5.5" board + 1/4" gap = 5.75" pitch across the 12 ft depth) ---
const rowPitch = (5.5 + 0.25) / 12;           // ft
const rows = Math.ceil(D / rowPitch);         // number of 16 ft boards
const deckBoards = Math.ceil(rows * 1.10);    // +10% waste/breakage

// --- Railing (3 open sides = 16 + 12 + 12 = 40 lineal ft) ---
const railLf = W + D + D;                      // 40
const railSections8 = Math.ceil(railLf / 8);   // 8 ft kits
